lert((await p('question',{question:document.querySelector('#q').value})).message||'Done');document.querySelector('#report').onclick=async()=>{let d=prompt('What information is incorrect?');if(d)alert((await p('report',{reason:'Incorrect information',details:d})).message||'Done')};document.querySelector('#claim')?.addEventListener('click',async()=>{let n=prompt('Your name');if(!n)return;let ph=prompt('Phone (optional)')||'';let em=prompt('Email (optional)')||'';alert((await p('claim_business',{name:n,phone:ph,email:em})).message||'Done')});</script><?php sk1100_render_ai_widget('public');?> </body></html>